entries[257511] = { ["name"] = "Harnisch des Bronzewildlings", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die majestätischen Wildlinge winden sich durch die Lüfte, frei wie die ungebundenen Magien, die sie in der Luft halten.\"\nErfolg:\nMeister der turbulenten Zeitwege IV\nKategorie:\nZeitwanderung" }
entries[257513] = { ["name"] = "Harnisch des Bronzeaquilons", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die verlässlichen Rösser der Bastion sollen die stolzen und edlen Krieger der Aufgestiegenen widerspiegeln.\"\nErfolg:\nMeister der turbulenten Zeitwege IV\nKategorie:\nZeitwanderung" }
entries[257514] = { ["name"] = "Harnisch der bronzenen Leichenfliege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Es kostet einiges an Mühe, eine Leichenfliege zu schmücken, doch manch einer würde sagen, dass es das wert ist.\"\nErfolg:\nMeister der turbulenten Zeitwege IV\nKategorie:\nZeitwanderung" }
entries[257515] = { ["name"] = "Kleiner Grubert", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
entries[257516] = { ["name"] = "Harnisch der bronzenen Grabschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Auch wenn die bevorzugte Ästhetik der Bewohner von Revendreth eher düster und ominös ist, gibt es doch noch einige, die strahlenden Glanz bevorzugen.\"\nErfolg:\nMeister der turbulenten Zeitwege IV\nKategorie:\nZeitwanderung" }
entries[257518] = { ["name"] = "Kleine Höllga", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:" }
