entries[258423] = { ["name"] = "Gigantischer Grrloc", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der größte Murloc, den Ihr je gesehen habt!\"\nWoW-Shop" }
entries[258425] = { ["name"] = "Gigantischer Grrloc", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der zweitgrößte Murloc, den Ihr je gesehen habt!\"\nWoW-Shop" }
entries[258427] = { ["name"] = "Bezähmter Blizzard", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Flockengestöber als fordernder Freund, frostklirrend für verfrorene Freude.\"\nPromotion:" }
entries[258428] = { ["name"] = "Schneesturm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er kam aus Schnee und Eis in die Sonne von Azeroth, die brennt so heiß.\"\n30. Geburtstag von Blizzard" }
entries[258429] = { ["name"] = "Mondberührter Netherwelpe", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Netherwelpen beschwören oder wieder freigeben.\n80 ( 80)" }
entries[258430] = { ["name"] = "Wanderndes Urtum", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Urtume sind standhafte Verteidiger der Wälder Azeroths, sie sind aber auch für ihre eindrucksvollen Kronen aus Blättern bekannt, die im Wechsel der Jahreszeiten ihre Farbe ändern.\"\nPromotion" }
entries[258431] = { ["name"] = "Sarges Geschichte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Moment mal, Sarge ist doch gar nicht so groß. Da muss jemand im Hearthstone-Gasthaus eine ziemliche Räuberpistole erzählt haben...\"\nPromotion" }
entries[258432] = { ["name"] = "Drakks", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Drakks beschwören oder wieder freigeben.\n80 ( 80)" }
entries[258475] = { ["name"] = "Küstengleiter der Tuskarr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Tuskarr haben schon vor langer Zeit gelernt, dass die Knochen der von ihnen gejagten Meerestiere leicht sind, viel Auftrieb bieten und daher hervorragend als Material für Gleiter geeignet sind.\"\nPromotion" }
entries[258476] = { ["name"] = "Frostbrutprotowyrm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieselbe Magie des Untodes, die die Frostbrut zu Dienern des Lichkönigs werden ließ, hat diesen urtümlichen Wyrm erfüllt. Seine Loyalität und Kraft stehen jetzt im Dienste derer, die Azeroth verteidigen.\"\nPromotion:\nWrath of the Lich King Classic" }
entries[258477] = { ["name"] = "Telix das Sturmhorn", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Telix war einst ein einfacher Käfer auf der Verbotenen Insel und wurde dann von Sturmmagie erfüllt, als Raszageth befreit wurde. Mit seinen neuen geschärften Sinnen streift Telix nun auf den Dracheninseln an der Seite der Drachenschuppenexpedition umher... und Eurer!\"\nPromotion" }
entries[258479] = { ["name"] = "Algarischer Sturmreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren algarischen Sturmreiter oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese blitzerfüllte Krähe fliegt sogar bei den schwierigsten Wetterbedingungen und wurde dafür ausgebildet, durch die Himmel der Insel von Dorn und die Tiefen darunter zu segeln.\"\nPromotion:\nThe War Within Heroic Edition" }
entries[258481] = { ["name"] = "Gnomelia Gierhart", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[258482] = { ["name"] = "Ysergel", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[258483] = { ["name"] = "Lot", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick König Gobbi beschwören oder wieder freigeben.\n80 ( 80)" }
entries[258488] = { ["name"] = "Himmelspfotenglimmerpelz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Das Fell eines Glimmerpelzes nimmt die Eigenschaften seiner Umgebung an, ähnlich wie eine Tarnung. Muster eines strahlend blauen Himmels und majestätischer weißer Wolken haben diesem Glimmerpelz den Spitznamen \"Himmelspfote\" eingebracht.\"\nVerkäufer:\nSammler Ta'steld\nZone:\nOribos\nKosten:\n5.000" }
entries[258515] = { ["name"] = "Purpurlupin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einst sehnten die Ersten sich nach Schöpfungen mit einer wilden Ergebenheit, die sie nach eigenem Willen formen können. Die Wölfe von Zereth Mortis gehören zu ihren vielen Schöpfungen, wobei jene mit purpurner Gestalt die Mächtigsten unter ihnen sein sollen.\"\nVerkäufer:\nSammler Ta'steld\nZone:\nOribos\nKosten:\n5.000" }
