entries[259227] = { ["name"] = "Boxer-Bruno", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Bruno soll noch schlanker und sogar noch gemeiner als der ehrenwerte Bruce sein. Sein Vermächtnis wird gerade erst geschrieben.\"\nVerkäufer:\nUlaani\nZone:\nBizmos Boxbar\n\nVerkäufer:\nTiana Nimmermorn\nZone:\nShlae'gararena\n\nFraktion:\nKampfgilde (Rang 6)\nKosten:\n4." }
entries[259238] = { ["name"] = "Renitente Reitrakete", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das perfekte Transportmittel für einen Kämpfer, der sein Ziel nie verfehlt.\"\nVerkäufer:\nUlaani\nZone:\nBizmos Boxbar\n\nVerkäufer:\nTiana Nimmermorn\nZone:\nShlae'gararena\n\nFraktion:\nKampfgilde (Rang 8)\nKosten:\n10." }
entries[259454] = { ["name"] = "Ensemble: Ornat der gefesselten Elemente", ["text"] = "Heroisch\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Sammelt die Vorlagen dieses Rüstungssets. Diese Vorlagen können nur von Rufern, Jägern und Schamanen verwendet werden." }
entries[259463] = { ["name"] = "Schneepfotenglimmerpelzstreuner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Die Schneepfoten bewohnen die kalten Nachleben der Schattenlande und genießen ihre frostige Umgebung. Reisende, die den tödlichen Schneestürmen von Nordend verloren geglaubt waren, wurden manchmal wundersamerweise lebendig aufgefunden. Sie erzählten dabei, dass sie ihre Leben den geheimnisvollen Füchsen verdankten, die sie beschützt hatten.\"\nVerkäufer:\nSammler Ta'steld\nZone:\nOribos\nKosten:\n5.000" }
entries[259894] = { ["name"] = "Perfekte Konservierungsstoffe", ["text"] = "Handwerksmaterial\n\"Eine kleine Prise reicht bereits, um besondere Gerichte ewig haltbar zu machen! Lebensmittel sind nach Gebrauch nicht mehr genießbar.\"\nVerkaufspreis:" }
entries[259898] = { ["name"] = "Angegraute Drachenschuppenkappe", ["text"] = "Legion Remix\nWird beim Aufheben gebunden\nKopf Kette\n5 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\n80 ( 80)" }
