entries[265822] = { ["name"] = "Instabiler Mechagonstandortwechsel", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wechselt Euren Standort zur legendären Insel Mechagon. (8 Sek. Abklingzeit)\n\"Ein sicherer Transport ist so gut wie garantiert. Vorsicht: Nur für Einwegtransport geeignet.\"" }
entries[265922] = { ["name"] = "Begleiterausbildungshandbuch: Hol' die Beute", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenutzen: Lehrt den Befehl 'Hol' die Beute!'.\nBefiehlt Eurem Tier, die Beute von einem Leichnam innerhalb von 40 Metern aufzulesen.\nVerkaufspreis:" }
entries[265923] = { ["name"] = "Begleiterausbildungshandbuch: Tot spielen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Jäger\nBenutzen: Lehrt den Befehl 'Tot spielen'.\nEuer Begleiter stellt sich tot, sodass Gegner ihn ignorieren. Hält bis zu 6 Min. lang an.\nVerkaufspreis:" }
entries[267012] = { ["name"] = "Entwürfe des großen Architekten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nKlassen: Jäger\nBenutzen: Schaltet die Artefaktvorlage \"Arm der Titanen\" für Titanenblitz frei.\n\"Detaillierte Pläne für ein wahres Meisterwerk technomagischer Bogenbaukunst, dessen Kern eine mächtige, von Titanen geschmiedete Energiequelle birgt. Wie diese Pläne den Weg aus Mimirons Archiv gefunden haben, ist unbekannt.\"\nVerkaufspreis:" }
